questionvariables.text:
mean1:rand(5)+10;
sd1:rand(3)+2;
ds1:rand(900)+100;
list:makelist(float(quantile_normal(rand(1.0),mean1,sd1)),i,1,ds1);
lx:sort(list);
lim1:lx[1];
lim2:lx[ds1];
med:median(lx);
lq:quantile (lx,1/4),numer;
uq:quantile (lx, 3/4),numer;
xmin:lx[1]-2;
xmax:lx[ds1]+2;
ymin:-4;
ymax:8;

aa:rand(2.0);
bb:rand(3.0);
mean2:mean1+(rand(5)+10)*aa;
sd2:sd1*bb;
ds2:ds1;
list2:makelist(float(quantile_normal(rand(1.0),mean2,sd2)),i,1,ds2);
lx1:sort(list2);
lim11:lx1[1];
lim21:lx1[ds2];
med11:median(lx1);
lq1:quantile (lx1,1/4),numer;
uq1:quantile (lx1, 3/4),numer;
xmin:lx[1]-2;
xmax:lx[ds2]+2;
ymin:-4;
ymax:8;

aa1:rand(3.0);bb1:rand(3.0);mean2:mean1+(rand(5)+10)*aa1;sd2:sd1*bb1;ds2:ds1;
list2:makelist(float(quantile_normal(rand(1.0),mean2,sd2)),i,1,ds2);lx1:sort(list2);
lim11:lx1[1];lim21:lx1[ds2];med11:median(lx1);lq1:quantile (lx1,1/4),numer;
uq1:quantile (lx1, 3/4),numer;xmin:lx[1]-2;xmax:lx[ds2]+2;ymin:-1;ymax:8;

aa3:rand(4.0);bb3:rand(6.0);mean3:mean2+(rand(7)+10)*aa3;sd3:sd1*bb3;ds3:ds2;
list3:makelist(float(quantile_normal(rand(1.0),mean3,sd3)),i,1,ds3);lx3:sort(list3);
lim33:lx3[1];lim31:lx3[ds3];med33:median(lx3);lq3:quantile (lx3,1/4),numer;
uq3:quantile (lx3, 3/4),numer;xmin3:lx3[1]-2;xmax3:lx3[ds3]+2;ymin:-1;ymax:8;

s_aa:rand([-1,0,1]);
s_bb:rand([1/3,1/2,1,2,3]);
dun1:makelist(round(float(quantile_normal(rand(1.0),mean1,sd1))),i,1,ds1);
mdun1:float(mean(dun1));
r_mdun1:round(mdun1);
sddun1:round(float(std1(dun1)));
dorx1:sort(dun1);
dun2:makelist(round(float(quantile_normal(rand(1.0),mean2,sd2))),i,1,ds2);
mdun2:float(mean(dun2));
mdiff:float(mdun1-mdun2);
dun2: if s_aa =0 then dun2+mdiff else dun2;
mdun2:float(mean(dun2));
r_mdun2:round(mdun2);
sddun2:round(float(std1(dun2)));
dorx2:sort(dun2);

maxfreq1:0;
k:1;
for i:2 thru ds1 do if dorx1[i]=dorx1[i-1] then (k:k+1, if maxfreq1 < k then maxfreq1:k) else k:1;
maxfreq2:0;
k:1;
for i:2 thru ds2 do if dorx2[i]=dorx2[i-1] then (k:k+1, if maxfreq2 < k then maxfreq2:k) else k:1;

xmin:if dorx1[1]<=dorx2[1] then dorx1[1]-2 else dorx2[1]-2;
xmax:if dorx1[ds1]>=dorx2[ds2] then dorx1[ds1]+2+(dorx1[ds1]-dorx1[1])/1.5 else dorx2[ds2]+2+(dorx2[ds2]-dorx2[1])/1.5;
ymin:-4;
ymax: maxfreq1+maxfreq2+5;

j:1;
dory1:makelist(0,i,1,ds1);
dory1[1]:1+maxfreq2+3;
for i:2 thru ds1 do if dorx1[i]=dorx1[i-1] then (j:j+1, dory1[i]:j+maxfreq2+3) else (j:1, dory1[i]:j+maxfreq2+3);
j:1;
dory2:makelist(0,i,1,ds2);
dory2[1]:1;
for i:2 thru ds2 do if dorx2[i]=dorx2[i-1] then (j:j+1, dory2[i]:j) else (j:1, dory2[i]:j);
